async function mergeDocumentPoint(page,x,y){return page.evaluate(({x,y})=>{const state=window.SpriteStudioTest.mergeState(),rect=document.querySelector('#mergeCanvas').getBoundingClientRect();return{x:rect.left+state.view.ox+x*state.view.scale,y:rect.top+state.view.oy+y*state.view.scale}},{x,y})}
async function dragMergeAt(page,from,to){const a=await mergeDocumentPoint(page,...from),b=await mergeDocumentPoint(page,...to);await page.mouse.move(a.x,a.y);await page.mouse.down();await page.mouse.move(b.x,b.y,{steps:4});await page.mouse.up()}
async function mergePixel(page,x=40,y=40){return page.evaluate(({x,y})=>{const state=window.SpriteStudioTest.mergeState(),canvas=document.querySelector('#mergeCanvas'),dpr=devicePixelRatio||1;return [...canvas.getContext('2d').getImageData(Math.round((state.view.ox+x*state.view.scale)*dpr),Math.round((state.view.oy+y*state.view.scale)*dpr),1,1).data]},{x,y})}


