function baselinePng(){const p=new PNG({width:360,height:440});for(let y=80;y<=420;y++)for(let x=145;x<215;x++){const i=(y*360+x)*4;p.data[i]=90;p.data[i+1]=120;p.data[i+2]=80;p.data[i+3]=255}return PNG.sync.write(p)}
async function toolGeometry(page,selectors){return page.evaluate(selectors=>selectors.map(selector=>{const button=document.querySelector(selector),icon=button.querySelector('.tool-icon'),label=button.querySelector('.tool-label'),b=button.getBoundingClientRect(),i=icon.getBoundingClientRect(),l=label.getBoundingClientRect();return{selector,button:{left:b.left,right:b.right,top:b.top,bottom:b.bottom,width:b.width,height:b.height},icon:{left:i.left,right:i.right,top:i.top,bottom:i.bottom,center:(i.left+i.right)/2},label:{left:l.left,right:l.right,top:l.top,bottom:l.bottom,center:(l.left+l.right)/2,scrollWidth:label.scrollWidth,clientWidth:label.clientWidth}}}),selectors)}
function expectIconOverLabel(items){for(const item of items){expect(Math.abs(item.icon.center-item.label.center),item.selector).toBeLessThanOrEqual(2);expect(item.icon.bottom,item.selector).toBeLessThanOrEqual(item.label.top);expect(item.label.scrollWidth,item.selector).toBeLessThanOrEqual(item.label.clientWidth);expect(item.button.height,item.selector).toBeGreaterThanOrEqual(44)}for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){const a=items[i].button,b=items[j].button;expect(a.right<=b.left||b.right<=a.left||a.bottom<=b.top||b.bottom<=a.top,`${items[i].selector} overlaps ${items[j].selector}`).toBe(true)}}

